package com.alfa.device_ctrl;
import android.app.Activity;import android.content.Intent;import android.graphics.Color;import android.net.Uri;import android.os.Bundle;import android.provider.Settings;import android.view.Gravity;import android.widget.Button;import android.widget.LinearLayout;import android.widget.TextView;
/** Real overlay permission/state gate and launcher for the live floating PTY. */
public final class FloatingTerminalActivity extends Activity implements RuntimeSessionManager.Listener{private TextView state;private RuntimeSessionRegistry registry;@Override protected void onCreate(Bundle b){super.onCreate(b);registry=RuntimeSessionRegistry.get(this);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(dp(14),dp(14),dp(14),dp(14));r.setBackgroundColor(Color.rgb(19,19,21));TextView t=new TextView(this);t.setText("FLOATING TERMINAL");t.setTextColor(Color.rgb(171,199,255));t.setTextSize(16);r.addView(t,new LinearLayout.LayoutParams(-1,dp(50)));state=new TextView(this);state.setTextColor(Color.rgb(193,198,213));state.setTextSize(11);state.setTypeface(android.graphics.Typeface.MONOSPACE);r.addView(state,new LinearLayout.LayoutParams(-1,dp(120)));Button permission=new Button(this);permission.setText("OPEN OVERLAY PERMISSION");permission.setMinHeight(dp(48));permission.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION, Uri.parse("package:"+getPackageName()))));r.addView(permission);Button start=new Button(this);start.setText("START FLOATING TERMINAL");start.setMinHeight(dp(48));start.setOnClickListener(v->startFloating());r.addView(start);Button stop=new Button(this);stop.setText("STOP FLOATING TERMINAL");stop.setMinHeight(dp(48));stop.setOnClickListener(v->RuntimeKeepAliveService.hideFloatingOverlay());r.addView(stop);TextView note=new TextView(this);note.setText("Overlay uses TYPE_APPLICATION_OVERLAY and requires explicit SYSTEM_ALERT_WINDOW authorization. Runtime execution remains evidence-bound.");note.setTextColor(Color.rgb(193,198,213));note.setTextSize(10);note.setPadding(0,dp(12),0,0);note.setGravity(Gravity.TOP);r.addView(note,new LinearLayout.LayoutParams(-1,0,1));setContentView(r);refresh();}@Override protected void onResume(){super.onResume();refresh();}private void startFloating(){if(!Settings.canDrawOverlays(this)){state.setText("OVERLAY=BLOCKED\nreason=SYSTEM_ALERT_WINDOW not granted");return;}String id=AlfaSettingsStore.get(this).getRuntimeId(RuntimeSelection.DEFAULT_RUNTIME_ID);try{RuntimeSessionManager m=registry.start(id,this,80,24,8,16);RuntimeKeepAliveService.showFloatingOverlay(this,m);state.setText("OVERLAY=REQUESTED\nRUNTIME="+id+"\nSESSION="+(m.isPromptReady()?"READY":"WAITING"));}catch(Exception e){state.setText("OVERLAY=BLOCKED\n"+e.getClass().getSimpleName()+":"+e.getMessage());}}private void refresh(){state.setText("SYSTEM_ALERT_WINDOW="+(Settings.canDrawOverlays(this)?"GRANTED":"DENIED")+"\nFGS_ACTIVE="+RuntimeKeepAliveService.isActive()+"\nSESSIONS="+registry.size()+"/"+registry.capacity());}@Override public void onState(String v){runOnUiThread(()->state.setText("SESSION_STATE="+v+"\nSESSIONS="+registry.size()+"/"+registry.capacity()));}@Override public void onTextChanged(){}@Override public void onSessionFinished(int e){runOnUiThread(()->state.setText("SESSION_FINISHED="+e));}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}}
